quests[62312] = { id = 62312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Gunn Gorgebone", objectives = "We've got an exciting development today, {name}!\n\nYou must have made quite an impression. Gunn Gorgebone, one of the champions of the Theater of Pain, is demanding to join our ranks here. Demanding it!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62313] = { id = 62313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Rencissa the Dynamo", objectives = "{name}! Step closer, come, come!\n\nI've just received word that none other than Rencissa the Dynamo is on her way here to fight for you. Rencissa! The Dynamo!\n\nWho should we have her kill first?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62314] = { id = 62314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Khaliiq", objectives = "Listen up, {name}. We need more eyes out there on the battlefield.\n\nThere's too many threats, and not enough information flowing our way.\n\nSee if Khaliiq is up to the task. You heard me right, I said more Eyes!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62315] = { id = 62315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Plaguey", objectives = "We've got a strange one today, {name}.\n\nMarileth stopped by to say that his slime Plaguey is feeling more blue than usual, and asked if we could keep him entertained.\n\nWhat does this look like, a kennel? Plaguey can earn his keep like the rest of us! Get him out there, soldier!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62316] = { id = 62316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurer: Rathan", objectives = "Your dedication to Maldraxxus is inspiring, {name}.\n\nRathan has requested to join our ranks here at the Seat, for the good of Maldraxxus. His expertise will be a welcome addition!\n\nI suspect he wants to keep an eye on Emeni as well, but you didn't hear that from me.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62317] = { id = 62317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Casting Doubt", description = "<A note has been left here for Kel'Thuzad. It does not appear that he has read it.>\n\nBaron, I do not trust your new favorite acolyte. Something has been off about them ever since they returned from their ritual with the Kyrian remains.\n\nYour work is too important to allow such discrepancies. The acolyte should be disposed of.\n\nFaithfully,\n\nSorcerer Vutral", objectives = "Defeat Sorcerer Vutral in the Vault of Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62320] = { id = 62320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regalia de Rigueur", description = "Ah, if it isn't Kel'Thuzad's favorite acolyte? I simply cannot understand how a baron like him would surround himself with such... homely company.\n\nWhen was the last time you even chanced at a looking glass? Those faded robes do your station no justice.\n\nI would take it upon myself to update your drab apparel, if I weren't sufferring such a shortage on the house's preferred amethystine tint.\n\nYou could always fetch some yourself. The sorcerers usually have some stashed among their tomes and altars.", progress = "I will need large quantities of amethystine powder if I am to fix...\n\n<Moret gestures at you broadly.>\n\n...this.", completion = "It brings me great relief that your pallid vestments will no longer offend my vision.\n\nDo try keep them in better repair henceforth.", objectives = "Collect 10 Amethystine Powder from the House of Rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
