quests[62361] = { id = 62361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Introductions are in Order", description = "Now yous is all set with yer new dredger, go ahead call on them and officially introduce yerself.", completion = "I am so confused...", objectives = "Talk with your new Dredger Butler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62362] = { id = 62362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volatile Reactions", description = "The living slime within Maldraxxus naturally produces a powerful catalyst used in many of the House of Eyes's poisons. There is always a need for the substance.\n\nIt would be of great help if you could retrieve some for us.", progress = "Worry not, despite its appearance the catalyst is not toxic on its own.", completion = "A respectable amount. We will make good use of this.", objectives = "Collect 15 animated catalysts from the slime around Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62363] = { id = 62363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy Lifting", description = "The stronger members of the House of the Chosen tend to take a fairly specific form. No doubt you've seen the larger warriors in the house?\n\nThey are the greatest threat in their collective force. Thin them out.", completion = "I must thank you. We are no match for the Chosen when it comes to brute strength.", objectives = "Kill 20 warriors of the House of the Chosen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62364] = { id = 62364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dire Learning", description = "Necromancers and liches often use powerful tomes to assist in their rituals. Now that the House of Rituals has expanded their reach, the tomes can be found anywhere where their members are active.\n\nFind these books and destroy them. It won't end their vile experiments but it should at least delay them.", completion = "Good. The House of Rituals will learn not to make enemies of the House of Eyes.", objectives = "Destroy 15 Tome of Rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62365] = { id = 62365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Careful Creations", description = "What better way to stop our enemies in their tracks than to use their own experiments against them?\n\nLucky for us, some of our... friends have left a few samples unattended. And I know just where to test it...\n\nAs menacing as they may be, those abominations down there are delicate creations.\n\nIt would be a shame if you were to get your hands on some of their equipment and disrupt the process...", progress = "Everything going as planned?", completion = "Hah! That worked better than expected. They'll be busy cleaning up that mess for a while!\n\nOh, um...\n\n<Darkrider Arly points at your shoulder.>\n\nStill got a little bit on you...", objectives = "Locate an Experimental Blightspreader. Fill it with Experimental Fluid. Use the blightspreader to destroy 3 Reconstructed Abominations at The Fleshwerks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62366] = { id = 62366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 3" }
quests[62367] = { id = 62367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 1" }
quests[62368] = { id = 62368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebuild Our Trust", description = "Well {name}, it seems you are serious about earning your way back into our good graces.\n\nIt seems you are serious about this penance. This task should prove your willingness to rejoin our ranks.", completion = "So, you have done as we ask and are ready to rejoin our ranks?\n\nOnce you complete this task with me you will leave your current Covenant and rejoin the Kyrian.", objectives = "Complete the task for the Kyrian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62371] = { id = 62371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirna Scithe: A Warning Silence", description = "The songs of Tirna Scithe have faded as the grove wanes, yet there is now silence. Droman Oulfarran's voice has not been heard in some time. The trees whisper of penumbral shadows, discordant songs, and dying roots. All is not well.\n\nFriend of Ardenweald, travel to Root-home. Delve into the Mists. Remove that which threatens us.", progress = "What has silenced the grove of Tirna Scithe?", completion = "Word of your aid has been sung through the roots. Thank you, friend of the forest.", objectives = "Defeat Tred'ova in The Mists of Tirna Scithe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62373] = { id = 62373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 2" }
quests[62374] = { id = 62374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 3" }
quests[62382] = { id = 62382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Unknown", description = "Come to pay old Marasmius a visit? I have a special task for you.\n\nOne of my shoots has found a strange place, a place even I've never seen before.\n\nI'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for!\n\nWhat do you say, {name}? Up for an adventure?", progress = "Keep your guard up. It could lead anywhere!", completion = "She seemed nice. The Mushroom Kingdom, was it? Hmph, never heard of it. Things kids get up to these days....", objectives = "Investigate the unknown area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62385] = { id = 62385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 1" }
quests[62386] = { id = 62386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 2" }
quests[62387] = { id = 62387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 3" }
quests[62388] = { id = 62388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "House of Rituals", description = "The Ritualists are the ones behind this war. Every act of treason has been committed under their orders.\n\nWe cannot defeat their sorcery with strength of arms alone. Victory will hinge on our knowledge of what they are plotting.\n\nContinue to bolster our forces. I will look for a way to infiltrate the House of Rituals.", completion = "It seems we may have our way into the House of Rituals.\n\nDo not mistake this lich for an ally. He pursues only his own agenda. But for now, our goals align... and we can use that to our advantage.", objectives = "Increase your Renown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62389] = { id = 62389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebuild Our Trust", description = "So you have taken the first step to reclaiming our trust.\n\nNow you must prove that was not another false start in our relationship. \n\nThis final task should prove your willingness to rejoin our ranks.", completion = "So, you have done as we ask and are ready to rejoin our ranks?", objectives = "Complete the task for the Venthyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62390] = { id = 62390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body Count", description = "I am acquainted with a few fleshcrafters who work outside of the House of Constructs. If we can find reagents for them, they can supply our war effort with constructs.\n\nThe House of Constructs has plenty of excess body parts. Find them and bring them back here.", progress = "We'll take any quality of parts you can find.", completion = "I will give these to the fleshcrafters. If we don't have enough soldiers, we will just have to build some.", objectives = "Collect 30 abomination parts from around Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62391] = { id = 62391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mobilize Maldraxxus", description = "It will be difficult to reach Kel'Thuzad while he is in his necropolis.\n\nGo now. It will take time for us to muster an army that can pierce his defenses.", completion = "Our forces stand ready.\n\nLet us end this.", objectives = "Increase your Renown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62392] = { id = 62392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebuild Our Trust", description = "You return as requested. Impressive, maybe you have indeed turned a new leaf.\n\nI wish to see you complete one more task for us. To prove your dedication to this transition. \n\nNot that we doubt you, but you must understand your previous behavior gives us reason to doubt that dedication.", completion = "So, you have done as we ask and are ready to rejoin our ranks?", objectives = "Complete the task for the Night Fae.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62393] = { id = 62393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rebuild Our Trust", description = "You still have the same strength you had before it seems.\n\nThe question is - do you have any loyalty left within you?\n\nI have one more task so you can demonstrate that loyalty again.", completion = "So, you have done as we ask and are ready to rejoin our ranks?\n\nOnce you complete this task with me you will leave your current Covenant and rejoin the Necrolords.", objectives = "Complete the task for the Necrolords.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62394] = { id = 62394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "House In Decline", description = "Our forces are gathering.\n\nSoon it will be time to move against the House of Rituals.\n\nSee what you can do to continue strengthening our position.", objectives = "Increase your renown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62400] = { id = 62400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", progress = "I feel a breeze on the other side. I guess that means it's not underground.", completion = "I remember those guys. Bad news. \n\nThey should stick to their own realm of existence!\n\nNice job cleaning house.", objectives = "Investigate the unknown area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62401] = { id = 62401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Scourgestones", description = "The Lich King's minions once carried scourgestones given to them by their dark master. \n\nNew ones have been found on the corpses of the undead. We do not know their purpose... but they have been touched by even more sinister magic.\n\nAs you slay the Scourge across Icecrown, keep your eyes open for such stones. If you bring them back to me, I shall turn them over to the confessors for study.", progress = "How goes your slaying of the undead?", completion = "I will turn these over to the confessors immediately. There is more to these scourgestones than it seems. \n\nPerhaps they will grant us more knowledge of the creatures that assail us from the rift in the sky.\n\nIf you find any additional scourgestones while you are adventuring, please bring them to me.", objectives = "Collect Darkened Scourgestones and Pitch Black Scourgestones from undead forces in Icecrown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62402] = { id = 62402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timewalking Campaigns" }
quests[62403] = { id = 62403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boared to Death", description = "The boars around Maldraxxus have a peculiar trait. Their tusks absorb liquid. Depending on where it has been, these bones may contain a powerful compound of poisons or other alchemical rarities.\n\nIt takes a trained eye to tell what the bone is made of, so just bring back a large amount of them. From there I will see if any of them are valuable.", progress = "Take care not to let any of the bones touch your skin for too long. They may cause irritation.", completion = "A fine amount. There will surely be something useful in this collection.", objectives = "Collect 25 bloody tusks from the boars in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62406] = { id = 62406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staff of the Primus", description = "The Staff of the Primus. The final piece of our leader's regalia.\n\nI can't deny the pride I feel in restoring this hall. You should feel the same sense of accomplishment.\n\nThe statue awaits you, {name}. Bring glory to this realm.", completion = "I sense power. Power and ease.", objectives = "Place the Staff of the Primus upon the Statue of the Primus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62407] = { id = 62407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herbicidal Tendencies", description = "My gas is the most potent in all of Maldraxxus, but I've heard some of the others saying that it's not the strongest in the Shadowlands. \n\nThey claim there are some plants in Ardenweald with a bloom that is far more pungent than my gas. Nonsense!\n\nLet's go and check these plants out. If their stench is as strong as the stories claim, I might even be able to mix them in with my own gas!", progress = "Having fun picking flowers?", completion = "How is it possible for him to smell even worse than before? \n\nUgh. At least he gets results.", objectives = "Help Gas Bag collect Rotbloom Petals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62414] = { id = 62414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burying Suspicion", description = "It will do us no good to disguise yourself as Nelesis if word reaches Kel'Thuzad that she was slain. \n\nYou must ensure that no one who sees you enter the cave survives.", completion = "You left none behind to raise alarm? Good.\n\nWe can proceed with the plan.", objectives = "Kill 10 Lichsworn forces outside the House of Rituals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62417] = { id = 62417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", progress = "I feel a breeze on the other side. I guess that means it's not underground.", completion = "Nothing wrong with picking flowers for a living. It's good, honest work.\n\nAnd giving those blasted spriggans a kick in the rear is worthwhile too. Nice job.", objectives = "Investigate the unknown area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62420] = { id = 62420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snapper Soul", description = "<The Snapper Soul is determined. The shape of the dragon turtle will be yours to call upon.>", completion = "Ah. The essence of the dragon turtle! A fine shape. It is now yours, should you choose to use it.", objectives = "Bring the Snapper Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62421] = { id = 62421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gulper Soul", description = "<The Gulper Soul is patient and calm. The shape of the Gulper will be yours to call upon.>", completion = "The shape of the Gulper is now yours to call upon and use.", objectives = "Bring the Gulper Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62422] = { id = 62422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ardenmoth Soul", description = "<The Ardenmoth is plentiful in Ardenweald. Delicate looking creatures, they have hidden strength. Their magic can soothe the most tortured soul... or send the unwary into an eternal sleep. The shape of the moth will be yours to call upon.>", completion = "Ah, the moth. Such beautiful creatures. Their shape is now yours to call upon.", objectives = "Bring the Ardenmoth Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62423] = { id = 62423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursine Soul", description = "<The Ursine Soul is stalwart and brave. The shape of the bear will be yours to call upon.>", completion = "Ah. The heart of the bear! A fine shape. It is now yours, should you choose to use it.", objectives = "Bring the Ursine Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62424] = { id = 62424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crane Soul", description = "<The Crane Soul dances with grace. The shape of the crane will be yours to call upon.>", completion = "The grace of the crane! A fine shape. It is now yours to call upon.", objectives = "Bring the Crane Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62425] = { id = 62425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veilwing Soul", description = "<Graceful, dangerous, powerful. No creature in Ardenweald is more respected for its fierce defense of its family or territory than the veilwing. \n\nYou have defeated a foe who endangered not only Ardenweald, but all of the Shadowlands. For this, Champion of Ardenweald, you have earned a special boon - the ability to call upon the essence of the veilwing and take their shape.>", completion = "You have shown rare bravery, {name}. For this the forest recognizes you. Let all know your ferocity in defending our borders, and the love you have for our charges.", objectives = "Bring the Veilwing Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62426] = { id = 62426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gryphon Soul", description = "<The Gryphon Soul is agile and swift. The shape of the gryphon will be yours to call upon.>", completion = "Ah! You are swift like the gryphon it seems. The shape of the gryphon is yours to call upon.", objectives = "Bring the Gryphon Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62427] = { id = 62427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hippogryph Soul", description = "<The Hippogryph Soul is intelligent and valiant. The shape of the hippogryph will be yours to call upon.>", completion = "Ah, the brave hippogryph. This shape is now yours to call upon.", objectives = "Bring the Hippogryph Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62428] = { id = 62428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Equine Soul", description = "<The Equine Soul is free-spirited and loyal. The shape of a horned horse will be yours to call upon.>", completion = "A majestic shape, for certain. It is now yours, should you choose to use it.", objectives = "Bring the Equine Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62429] = { id = 62429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leonine Soul", description = "<The Leonine sine Soul is powerful and brave. The shape of the lion will be yours to call upon.>", completion = "Ah, the lion. A wonderful shape. It is now yours to use.", objectives = "Bring the Leonine Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62430] = { id = 62430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moose Soul", description = "<The Moose Soul endures and protects. The shape of the moose will be yours to call upon.>", completion = "The moose! A fine choice. It will be yours to call upon.", objectives = "Bring the Moose Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62431] = { id = 62431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowstalker Soul", description = "<The Shadowstalker Soul is cunning and careful. The shape of the Shadowstalker will be yours to call upon.>", completion = "The shadowstalker! You may use this shape to lurk within the forests.", objectives = "Bring the Shadowstalker Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62432] = { id = 62432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Owlcat Soul", description = "<The Owlcat Soul is a curious trickster, a beast of many parts working together in a playful balance, always seeking the next challenge. The shape of the owlcat will be yours to call upon.>", completion = "Ah, yes. You have overcome many challenges with teamwork. I can see why the owlcat is now a shape you may call upon.", objectives = "Bring the Owlcat Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62433] = { id = 62433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Soul", description = "<The Raptor Soul is loyal and fierce. The shape of the raptor will be yours to call upon.>", completion = "Ah, the raptor! This shape is now yours to use if you so desire.", objectives = "Bring the Raptor Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62434] = { id = 62434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runestag Soul", description = "<The Runestag Soul is calm and enduring. The shape of the Runestag will be yours to call upon.>", completion = "The runestag! Long have they been companions of the Night Fae. Their shape is now yours to use.", objectives = "Bring the Runestag Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62435] = { id = 62435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stag Soul", description = "<The Stag Soul is noble and mighty. The shape of the stag will be yours to call upon.>", completion = "Ah, the stag. This shape is now yours to call upon.", objectives = "Bring the Stag Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62436] = { id = 62436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrieker Soul", description = "<The Shrieker Soul is swift and fierce. The shape of the veil shrieker will be yours to call upon.>", completion = "The shape of the veil shrieker is now yours to use if you choose.", objectives = "Bring the Shrieker Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62437] = { id = 62437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiger Soul", description = "<The Tiger Soul is proud and strong. The shape of the tiger will be yours to call upon.>", completion = "The shape of the tiger is now yours to call upon.", objectives = "Bring the Tiger Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62438] = { id = 62438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lupine Soul", description = "<The Lupine Soul is a fierce and free-spirited protector. The shape of the wolf will be yours to call upon.>", completion = "Ah, the wolf. A fine shape. You may now call upon the wolf as a soulshape to use.", objectives = "Bring the Lupine Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62439] = { id = 62439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfhawk Soul", description = "<The Wolfhawk Soul is cunning hunter. The shape of the wolfhawk will be yours to call upon.>", completion = "The wolfhawk! Such an impressive hunter. Their shape is now yours to use.", objectives = "Bring the Wolfhawk Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62440] = { id = 62440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wyvern Soul", description = "<The Wyvern Soul is proud and determined. The shape of the wyvern will be yours to call upon.>", completion = "Ah, the wyvern. This shape is now yours to call upon.", objectives = "Bring the Wyvern Soul to Lady Muunn in the Heart of the Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62441] = { id = 62441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fair Exchange for a Soul", description = "While we work away here in the Conservatory, we must not forget to support the rest of the covenant.\n\nI am needed here, but you can range far, even though your legs are short. \n\nPlease, help our covenant recover the anima we need. I can then dedicate my time to preparing another spirit for you to restore.", progress = "Go, find more anima. I shall tend to the spirits while you do.", completion = "You continue to serve the conservatory well. For this you have my thanks.\n\nNow you may choose from the spirits I have collected myself for restoration.", objectives = "Collect anima for your Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62442] = { id = 62442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Covenant", description = "I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger.\n\nYou are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!.", completion = "I find it helpful to have you do these things for me.", objectives = "Complete a World Quest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62443] = { id = 62443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Covenant", description = "I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger.\n\nYou are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!.", completion = "I find it helpful to have you do these things for me.", objectives = "Complete a World Quest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62444] = { id = 62444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid the Covenant", description = "I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger.\n\nYou are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!", progress = "Head out into the Shadowlands. Return to me with stories of your exploits.", completion = "I find it helpful to have you do these things for me.", objectives = "Complete a World Quest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62445] = { id = 62445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spirit's Pride", description = "I seek to understand more about the prideful beings in this realm.\n\nIf you could place one in a wildseed, as you did for me, I could observe the restoration process.", progress = "Find a prideful spirit to restore. That is what I wish to see today.", completion = "This is nothing like my home world, but it is still quite fascinating.", objectives = "Place a Prideful Spirit into a wildseed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62447] = { id = 62447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare and Unusual Spirit", description = "I have a mystery for you, {name}!\n\nWho doesn't savor a good mystery? \n\nWe have found a spirit unlike any other, one who does not respond to being placed in a wildseed.\n\nEach of us who touched it experienced a dream in which we saw you battling a great beast. Only when you defeated it did the spirit begin on its path to rebirth. \n\nWe think we know the beast.\n\nAre you up for discovering if these dreams were a portent?", completion = "You did it! I cannot quite explain why that worked. Dreams can be strange, huh?", objectives = "Defeat Tred'ova in Mists of Tirna Scithe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62448] = { id = 62448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the House", description = "Your journey into the Maw was impressive, but it will take even more phenomenal feats to earn the loyalty of the Maldraxxi.\n\nIncrease your renown among our ranks, Maw Walker. The Maldraxxi are dedicated soldiers, but they will not follow just anyone into battle. Let your deeds prove your worth to them.", completion = "Your actions have attracted the attention of the other houses--and those who question their orders.", objectives = "Increase your Renown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62449] = { id = 62449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spirit's Duty", description = "I seek to understand more about the Dutiful beings in this realm.\n\nIf you could place one in a wildseed, as you did for me, I could observe the restoration process.", completion = "This is nothing like my home world, but it is still quite fascinating.", objectives = "Place a Dutiful Spirit into a wildseed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62450] = { id = 62450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spirit's Heart", description = "I seek to understand more about the Untamed beings in this realm.\n\nIf you could place one in a wildseed, as you did for me, I could observe the restoration process.", progress = "Find an Untamed spirit to restore. That is what I wish to see today.", completion = "This is nothing like my home world, but it is still quite fascinating.", objectives = "Place an Untamed Spirit into a wildseed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62451] = { id = 62451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Vestibule" }
quests[62452] = { id = 62452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Spirit's Might", description = "I seek to understand more about the Martial beings in this realm.\n\nIf you could place one in a wildseed, as you did for me, I could observe the restoration process.", progress = "Find a Martial spirit to restore. That is what I wish to see today.", completion = "This is nothing like my home world, but it is still quite fascinating.", objectives = "Place a Martial Spirit into a wildseed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62453] = { id = 62453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Unknown", description = "Come to pay old Marasmius a visit? I have a special task for you.\n\nOne of my shoots has found a strange place, a place even I've never seen before.\n\nI'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for!\n\nWhat do you say, {name}? Up for an adventure?", progress = "Keep your guard up. It could lead anywhere!", completion = "You know I appreciate hard work, but it's important to take care of yourself from time to time. Hope you had fun, blew off some steam, and are ready to get back at it!", objectives = "Investigate the unknown area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62454] = { id = 62454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare and Unusual Spirit", description = "I awaken. I exist once more. And yet...\n\nThere is an emptiness within. A lingering tether to a home that no longer exists. So much wonder... so much splendor... lost.\n\nNow I have no purpose. No fate. No path.\n\nWill you teach me of this place, awakener? I sense there is much to be understood. Many secrets. Many truths.\n\nIn so doing, perhaps a new fate will emerge.", progress = "Return to me when you have the essences from each realm.", completion = "Perhaps a new purpose awaits me.\n\nYou have rekindled my curiosity, at least.", objectives = "Speak to Falir and bring them essences from the realms of the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62456] = { id = 62456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De Other Side: Dealin' Wit' Da Boss", description = "Ay, mon. Long time no see!\n\nI be havin' a bit of trouble wit' me boss, Mueh'zala. Now, now... don't you worry. Your ol' friend Bwonsamdi got dis whole ting under control!\n\nI just be needin' some help gatherin' me mojo back from a few ungrateful business partners.\n\nYou bring me da mojo, and we goin' ta take care of ol' Mueh'zala once and for all!", progress = "First you get da mojo, then I get da powa'... then we be gettin' Mueh'zala!", completion = "Now dat da ol' boss be a captive audience, he and I goin' ta be makin' some new arrangements. Ya best be goin' now, but don't worry... I be seein' ya soon!", objectives = "Defeat Mueh'zala in De Other Side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62457] = { id = 62457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Vault", description = "\"The Purpose.\" Utter nonsense, of course.\n\nThe attendants are so blinded by devotion that you could drop stewards on their heads and say the Purpose told you to do so, and they'd ramble on about it being a mysterious portent of some grand destiny.\n\nKah-Toll is the most insufferable of all. I've been observing that vault for quite some time, and I assure you it has never opened for anyone.\n\nOf course, if someone COULD open it, I'd pay handsomely to know what's inside.", progress = "Perhaps I can convince Kah-Toll that the Purpose demands that the attendants should stand on their hands for a week.", completion = "So, you succeeded where others, myself included, have failed.\n\nFrom what I hear, that's the second time a relic of the First Ones responded to your presence.\n\nI must admit, I haven't the slightest idea how you managed it. Interesting. Very interesting indeed.", objectives = "Acquire a reward from the Great Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62458] = { id = 62458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De Other Side", description = "Ay, dere {name}! Ya be just da {class} I've been lookin' for!\n\nIt be your ol' pal Bwonsamdi reachin' out ta ya from De Other Side! I be havin' a little problem over here wit' de boss...\n\nYa be lookin' mighty bored just standin' around here in Ardenweald. Why don't ya come to De Other Side and help out an ol' friend? Bwonsamdi promise he gonna make it worth ya while!\n\nYa might want ta bring a few more adventurers wit' ya... just ta be safe.", completion = "Ay, dere mon! It be good ta see a friendly face. Your ol' friend Bwonsamdi be havin' a bit of trouble wit' da Bossman...", objectives = "Speak with the Mask of Bwonsamdi in De Other Side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62459] = { id = 62459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", progress = "I feel a breeze on the other side. I guess that means it's not underground.", completion = "Those are special moths! They really liven up the place, don't they?\n\nYou know moths work just as hard as anyone else, and they're under-appreciated. \n\nThanks for savin' em.", objectives = "Investigate the unknown area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62461] = { id = 62461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalking the Warrens", description = "So, they are creating magical beasts deep within the Warrens. Their power is... substantial.\n\nMaw Walker, I must trust in you to handle this. While I can provide insight, in combat I must admit your prowess exceeds my own.\n\nHunt the beasts that they train to hunt us. Show the Mawsworn that we too can bare fangs.", completion = "I suspect this will not be your last foray into the Warrens.", objectives = "Complete a Hunt in The Beastwarrens.\n\nSuggested Players [5]", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62462] = { id = 62462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Key of Eyes", description = "I seek a mercenary of unparalleled might to venture into the House of Eyes and procure the \"Key of Eyes\".\n\nAbove average compensation is assured for the one who can both deliver the key and regale me with the story of its previous owner's demise. \n\nBe warned that the grounds once belonging to the House of Eyes are extremely dangerous and lone exploration is highly discouraged.", progress = "So, you've seen my posting?", completion = "Ah, very good! And a million eyes appeared, you say? How frightening! \n\nGlad she's gone and the key's in my hands now! She used it to break into many a locked door, you know? A very powerful item! Very profitable too.\n\nAnd now it's mine!", objectives = "Eliminate Chelicera and obtain the Key of Eyes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62465] = { id = 62465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", progress = "I feel a breeze on the other side. I guess that means it's not underground.", completion = "Always nice to lend a hand to someone who's just tryin' to do their job. A metaphorical hand, obviously... although in your case, it's literal.\n\nI know what metaphorical means!\n\nAnyway, good work out there.", objectives = "Investigate the unknown area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62466] = { id = 62466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Go Beyond!", description = "Ah, you're just in time. I've made quite the discovery.\n\nI've managed to make a connection even further out than I ever have before.\n\nHow did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for!\n\nUp for an even more exciting adventure?", progress = "I feel a breeze on the other side. I guess that means it's not underground.", completion = "Must be nice to have the leisure to just sit and think all the time. \n\nI've barely got time myself, with all the work I have keeping this place together!\n\nStill, that was nice of you to help out the old turtle.", objectives = "Investigate the unknown area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62467] = { id = 62467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seed of a Thought", description = "Within wildseeds, spirits slumber and grow. But so too can catalysts, when seeds take the place of spirits.\n\nSeed Merchant Daybreak trades in such seeds. She can supply you with the ones you seek. Choose one to plant within a wildseed.\n\nThe forest holds its breath and awaits your choice.", progress = "Your talents as a cultivator continue to thrive.", completion = "The branches of your expertise reach for the heavens and blossom. This is good.", objectives = "Acquire a seed and plant it within a wildseed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62473] = { id = 62473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Old is New", description = "These damn Scourge make me sick!\n\n<Brollen spits on the ground.>\n\nThey're only good fer one thing--bein' dead!\n\nHead tae the valley southwest o' here. Plenty o' gear fer the pickin' over there!\n\nGather up what ye can. I'll make do with what ye find.", progress = "Find somethin' worth smeltin'?", completion = "These'll do nicely.\n\nI'll get tae work.", objectives = "Gather 8 Jagged Blades and 8 Battleworn Chainmail from the Conflagration.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62477] = { id = 62477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Skystrider Glider", description = "<You have discovered plans for a single use glider, invented by Dresaelus.\n\nDactylis should be able to help you with crafting this kit.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Skystrider Glider to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62483] = { id = 62483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steward Mail Pouch", description = "<The pouch is well constructed, with plenty of room for scrolls and a division to keep letters flat. The stitching is clean, and the strap is adjustable to fit your steward's size.\n\nYou are certain your steward will love it.>", completion = "New pouch? Wow! Holds so much stuff!\n\nCannot wait to use it. Must show Sika! Thank!", objectives = "Summon your steward companion via Summon steward, then give them the Steward Mail Pouch.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62484] = { id = 62484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werk In Progress", description = "We received an... unusual delivery recently. I'm still in a bit of shock.\n\nSome sort of flying contraption released a huge crate just overhead, parachute and all. If it weren't for the wind it would have landed nearby. Instead, it drifted down the hill below.\n\nThey left a note too. It would have been lost had it not been wrapped around a sizeable rock.\n\n<Darkrider Arly massages a spot on her forehead.>\n\nI don't know what it is, but if it'll help clear out the area, I'm all for it.", progress = "Any luck locating that thing?", completion = "I was not expecting that!", objectives = "Locate the delivery. Use the device on a Reconstructed Abomination, then destroy the Scourge presence at the Fleshwerks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62486] = { id = 62486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blueprint: Empyrean Refreshment", description = "<You have discovered plans for a table of refreshing snacks that would be quite useful while out adventuring.\n\nDactylis should be able to help you with the crafting.>", completion = "I see you have retrieved a new blueprint. I look forward to assisting you in your crafting.", objectives = "Bring the Blueprint: Empyrean Refreshment to Dactylis.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62536] = { id = 62536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost of Teldrassil", description = "I learned that Sylvanas burned Teldrassil. I felt my heart break for the night elves.\n\nAnd that was only the beginning. We know now that the souls lost that day did not go to their intended rest.\n\nBut you have the power to begin to correct that, Maw Walker.\n\nIf you find yourself in the Maw, look for any of those lost.\n\nPlease, bring them home.", completion = "Thank you, Maw Walker.\n\nYou have brought back a little bit of the light from the darkness.\n\nWe will make this right, no matter how long it takes.", objectives = "Travel to the Maw and rescue Lost Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62539] = { id = 62539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stygian Incinerator" }
quests[62544] = { id = 62544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From a Dark Place", description = "You rescued some of the night elves from the Maw before. While the danger is still great, I must ask you to do it again.\n\nI have to believe that we can save them. As many of them as possible.\n\nPlease, go and see if you can recover any more lost souls.", completion = "I thank you once again, Maw Walker.\n\nThese souls are finally free of the torment and pain.\n\nThere are still so many more, but I am optimistic that we may yet save them.", objectives = "Travel to the Maw and rescue Lost Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62546] = { id = 62546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Wisp Left Behind", description = "More of the Kaldorei souls still languish in the Maw.\n\nI ask you once again, Maw Walker, to find them.\n\nHelp correct this wrong.", completion = "It brings me joy to see more souls freed from that dark place.\n\nThank you Maw Walker, for continuing to help us.", objectives = "Travel to the Maw and rescue Lost Souls from the Tremaculum and the Planes of Torment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62549] = { id = 62549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Wisp Left Behind", description = "More of the Kaldorei souls still languish in the Maw.\n\nI ask you once again, Maw Walker, to find them.\n\nHelp correct this wrong.", completion = "It brings me joy to see more souls freed from that dark place.\n\nThank you Maw Walker, for continuing to help us.", objectives = "Travel to the Maw and rescue Lost Souls from the Tremaculum and the Planes of Torment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62553] = { id = 62553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delaying Their Efforts", description = "The Scourge continue to replenish their weapons of war from blighted grounds. Stopping their workers slows their production, but a decisive blow to their stockpiles would be far more effective.\n\nTake these and head to the area southeast of here. Plant the bombs, then make a quick exit.\n\nWeakening their supply lines should provide us ample time to retaliate.", completion = "Your dedication to the cause is much appreciated, {name}. You have once again put yourself at risk to ensure the safety of our allies.", objectives = "Plant the bombs at the Northern, Eastern and Western sites of The Bombardment. Remove 12 Decrepit Laborers from the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62554] = { id = 62554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sootible Hat: Red Noggin Candle", progress = "One of them Noggin Candles would impress 'em all, right?", completion = "That's right proper, that is!" }
quests[62555] = { id = 62555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Touch of Humility", description = "With the Temple of Humility under our control, its power shall flow back into the Crest of Ascension once more.\n\nJoin me below so that we may witness it together. Mikanikos has ensured it will become even more magnificent as its power grows.", completion = "The Archon shall convene the Paragons to discuss our next moves. Go in service.", objectives = "Witness the Crest of Ascension become empowered by the Temple of Humility.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62556] = { id = 62556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sootible Hat: Pink Party Hat", progress = "A Pink Party Hat is stylish an' classy, innit?", completion = "That's right proper, that is!" }
quests[62557] = { id = 62557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Realm Reclaimed", description = "Though Forsworn still fight across Bastion, the Temple of Loyalty is ours, and with it our realm.\n\nWe will have to stay diligent to maintain control of all of the temples, and much remains to be decided with the fate of our fallen brethren, but today is a day of great victory.\n\nJoin me at the Crest of Ascension, and witness its final empowerment.", completion = "This day would not have been won without you, Maw Walker.\n\nOn behalf of the Archon, the Paragons, and all kyrian--thank you.", objectives = "Witness the Crest of Ascension become empowered by the Temple of Loyalty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62558] = { id = 62558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sootible Hat: Fae Revel Masque", progress = "I gots to get one o' them Fae Revel Masques. Gonna keep 'em guessin' and be mysterious an' all.", completion = "That's right proper, that is!" }
quests[62559] = { id = 62559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sootible Hat: Crown of the Righteous", progress = "I knows what I needs! Everybody gonna bow down when they sees me in a Crown of the Righteous.", completion = "That's right proper, that is!" }
quests[62560] = { id = 62560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing in Power", description = "Wonderful news, {name}!\n\nYou have gathered enough Anima. The Queen is now able to empower the Heart of the Forest!", progress = "I am so excited!", completion = "We're on the right track, {name}! Keep doing what you're doing and it will be back to its full, glorious, starryness in no time!", objectives = "Witness the Winter Queen empower the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62561] = { id = 62561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Heart is Full", description = "{name}! Can you believe it? We have enough Anima that the Winter Queen can fully restore the Heart of the Forest!\n\nYou've done so much for us!", progress = "I am so excited!", completion = "We're so grateful for all your help, {name}. Seeing the Heart of the Forest like this again, full of power? My heart is filled with hope.", objectives = "Witness the Winter Queen empower the Heart of the Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62563] = { id = 62563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back Again!", description = "Gorgantus just won't give up!\n\nWe've defeated her several times already, but the scavengers salvage the body, fix her up and send her right back in here!\n\nShe thinks this time she will defeat us... prove her wrong.", completion = "You made that look easy. Let's hope she learned his lesson this time.", objectives = "Defeat Gorgantus the Gutter", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62567] = { id = 62567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Chromie's Call", description = "Chromie is seeking veteran adventurers to embark on expeditions through time and space.\n\nThis is your opportunity to experience the legendary adventures of the past--today!\n\nSpeak with Chromie near the Stormwind Embassy for more information.", completion = "I'm glad you made it, {name}! Something tells me that your future is waiting for you in the past!", objectives = "Speak with Chromie in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62568] = { id = 62568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adventurers Wanted: Chromie's Call", description = "Chromie is seeking veteran adventurers to embark on expeditions through time and space.\n\nThis is your opportunity to experience the legendary adventures of the past--today!\n\nSpeak with Chromie near the Orgrimmar Embassy for more information.", completion = "I'm glad you made it, {name}! Something tells me that your future is waiting for you in the past!", objectives = "Speak with Chromie in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62569] = { id = 62569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Jailer's Grasp", description = "By peering into the Maw, Bolvar drew the Jailer's attention.\n\nHis worst fears have come to pass.\n\nYou must help me break the link, {name}! The fragment of the Helm is the key!", completion = "The Jailer... is gone... from my mind.\n\nThank you, {name}. You saved me from a darker fate than you could ever know.\n\nFor that, you will ever have my thanks.", objectives = "Help Jaina Proudmoore sever the Jailer's connection to Bolvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62579] = { id = 62579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62584] = { id = 62584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frontline Resupply", description = "This forward camp relies heavily on our supply line from the tournament grounds. A recent shipment was attacked while in transit through the valley below us.\n\nSalvage what you can, and if possible, eliminate the threat so this does not happen again.", progress = "Caught in the frozen wastes, cold and alone... I only hope our allies put up a fight.\n\n<Crusader Renn shakes her head.>\n\nWere you able to salvage any of the shipment?", completion = "Thank you for your swift action, {name}.\n\nThese supplies should see us through to the next shipment.\n\nI will see to it that the bodies of those we lost are recovered and given their last rites.", objectives = "Recover 6 Salvaged Goods and kill 3 Retched Watchers in The Valley of Fallen Heroes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62587] = { id = 62587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Inner Calm", description = "I have always had dreams.\n\nSpecial dreams you could say.\n\nAny place of tranquility or calm can come to me in a dream.\n\nEven those that may have danger nearby, as calm can be found anywhere, if you know how.\n\nNow I dream of your world, your Azeroth. \n\nI cannot travel to your realm. Help me connect to my latest dream through your eyes.\n\nI have dreamed of a high place. A very high place. Do you know it?", completion = "That was such a pleasant dream. I am glad to you got to experience the reality.", objectives = "Travel to Highmountain in search of calm", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62588] = { id = 62588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Inner Calm", description = "You return.\n\nThis pleases me. \n\nMore places of tranquility have come to me in dreams.\n\nI see a sandy beach, Sunsets. \n\nI cannot travel to your realm. Help me connect to my latest dream through your eyes.", completion = "That was such a pleasant dream. I am glad to you got to experience the reality.", objectives = "Travel to Zuldazar to meditate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62589] = { id = 62589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Inner Calm", description = "I am glad you wish to continue your meditations.\n\nIt will help you be more centered.\n\nI have had another dream. A warm dream of a cold place.\n\nIt is wrapped in white. Do you know of it?\n\nVenture there and experience the vista I saw in my dream.", completion = "That was such a pleasant dream. I am glad to you got to experience the reality.", objectives = "Meditate in Winterspring", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62590] = { id = 62590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Inner Calm", description = "Thank you for returning.\n\nI have had another dream. Another vision of your realm.\n\nIn this dream the sky danced above me. \n\nOn the edge of a cliff, in a northern land. \n\nSuch a sight to behold. \n\nYou must experience it for yourself.", completion = "That was such a pleasant dream. I am glad to you got to experience the reality.", objectives = "Meditate in Howling Fjord", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62591] = { id = 62591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Inner Calm", description = "We have already experienced so much together.\n\nI am grateful to have a companion on this voyage of discovery.\n\nYou walk where I can only project.\n\nYou touch that which I can only see.\n\nI have had another dream.\n\nAnother coast. A statue. \n\nA large statue of a little one. \n\nGo, seek out the view from my dream.", completion = "That was such a pleasant dream. I am glad to you got to experience the reality.", objectives = "Meditate in Booty Bay", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62592] = { id = 62592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Inner Calm", description = "You have come a long way.\n\nYou are almost prepared to access your inner calm anywhere.\n\nJust one more journey under my guidance. \n\nIt is a short one. Peace was here in this garden all along.\n\nOne more location of calm to experience.\n\nThen you shall shed your spiritual shackles. \n\nI shall be proud.", completion = "That was such a pleasant dream, I am glad to you got to experience the reality.", objectives = "Find the new meditation location within the Queen's Conservatory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62593] = { id = 62593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt: Death Elementals" }
quests[62597] = { id = 62597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonesmith Heirmir", description = "<Alexandros Mograine left you a very straightforward letter of introduction for a certain Bonesmith Heirmir in Maldraxxus.\n\nWhat aid might she be able to offer the Ember Court?>", completion = "What do you want, Maw Walker?", objectives = "Deliver Alexandros Mograine's letter to Bonesmith Heirmir in Maldraxxus.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62598] = { id = 62598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgelite Sophone", description = "<Polemarch Adrestes left you a very formal letter of introduction for Forgelite Sophone in Bastion.\n\nWhat aid might she be able to offer the Ember Court?>", completion = "I assume you have need of me, Maw Walker. What can I do for you?", objectives = "Deliver Polemarch Adrestes's letter to Forgelite Sophone in Bastion.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62599] = { id = 62599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormsmith Cavina", description = "<Hunt-Captain Korayn left you a terse letter of introduction to Gormsmith Cavina in Ardenweald.\n\nWhat aid might he be able to offer the Ember Court?>", completion = "Do you need some armor repaired?", objectives = "Deliver Hunt-Captain Korayn's letter to Gormsmith Cavina in Ardenweald.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62600] = { id = 62600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Inner Peace", description = "This is a lovely spot don't you think?\n\nI knew the myths of Ardenweald. \n\nEven glimpsed it in dream.\n\nYet it swells with tranquility unimagined. \n\nCalm is what my kind live for. Even in chaos.\n\nYou can always find calm. I can show you if you would like? \n\nI can sense a nearby convergence of calm. That will provide a suitable demonstration.", completion = "Do you see now? There is great power in being able to find calm. To be able to center ones self offer solace in even the most turbulent of times.", objectives = "Travel out into Ardenweald to commune with the calm of the land.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62601] = { id = 62601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgy", description = "<Rendle left you a crumpled envelope addressed to Forgy in Darkhaven. On the outside of the envelope are very specific orders to tell Forgy that Rendle sent you.\n\nWhat aid might Forgy be able to offer the Ember Court?>", completion = "What can I do for ya, Maw Walker?", objectives = "Deliver Rendle's letter to Forgy in Darkhaven.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62603] = { id = 62603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare and Unusual Spirit", description = "I'm glad to see you again, friend!\n\nWe have found another inert spirit gripped by dark dreams. Nasty stuff! \n\nIn this dream, a noble figure that once embodied loyalty has been consumed by their own doubts, leading them down a dark path.\n\nIf you were to defeat the fallen paragon, I bet we'll be able to revive this poor spirit.\n\nWill you help us once more, {name}?", completion = "Another dream vision fulfilled. This is remarkable!", objectives = "Defeat Devos in the Spires of Ascension.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62605] = { id = 62605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broker Business", description = "<A web covered box of assorted scholar supplies lays haphazardly on the ground. The make seems Broker in origin. Perhaps the owner is nearby.>", completion = "Oh! My missing supplies! How fortuitous.", objectives = "Find the owner of the forgotten supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62606] = { id = 62606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blackthorn Blend", description = "Ah, just the mushroomancer I wanted to see! Mind getting me some clay?\n\nThere's all kinds of different soil, you know. It's not all just dirt! And clay... clay is something special. You ever try growing through clay? Oh, I guess not.\n\nIt's hard work to break down, but once you do the flavor is incomparable! My roots are looking forward to the challenge.\n\nBlackthorn Grove has a particularly bitter and complex clay that is just what I'm craving. I'm sure they won't mind if you ask them for some.", progress = "If they give you any trouble, just tell 'em Marasmius sent you. I bet someone there is old enough to remember me.", completion = "Ooh, that's the stuff all right. It's bitter, sure, but wonderfully complex and subtle undertones. Mm! You'll have to try some sometime.", objectives = "Collect 6 Blackthorn Clay in Blackthorn Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62607] = { id = 62607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glittering Gritty Goodness", description = "Well, hello there! Fancy helping me out today?\n\nYou ever been to Shimmerbough? Ever wonder why it's called that? I was there when it was named, you know.\n\nLots of people think it's the trees or the water, and they're right. But the secret to the shimmering is in the silt. The soil soaks and gains excess anima from the water, until the ground itself practically sparkles.\n\nI could really go for some shimmersilt right now. Would you let an old mushroom relive his youth?", progress = "Oooh, I always used to get tingly all over when I had shimmersilt. And that's a lot of tingling!", completion = "Look at it sparkle and shine! I'm getting the tingles just looking at it. I feel ages younger already!", objectives = "Collect 6 Shimmersilt in Shimmerbough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62608] = { id = 62608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Treat", description = "So nice to see you again. I've got a special request for you.\n\nThe Winter Queen herself used to tend directly to groves, in the early times. Everything she touched burst with life and power. Even the ground she walked on.\n\nOver time, the Queen's Garden came to be known as the Garden of Night, for the Queen had not tended to her garden in so long.\n\nBut the ground is still potent with her power. It's the finest meal I've ever had. I know this is indulgent, but you and I both know I deserve it!", progress = "Sometimes you just need to treat yourself to something nice.", completion = "Feel how luxurious the soil is! I'm going to savor this for a while. Thank you.", objectives = "Collect 6 Royal Peat in the Garden of Night.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62609] = { id = 62609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necrolord Arsenal", description = "<Bonesmith Heimir begins reading the letter you hand her.>\n\nHmm. Mograine usually has more sense than this...\n\n<Bonesmith Heimir finishes the letter and shreds it with her bony fingers.>\n\nAn order's an order. I'll arrange for a shipment of raw materials and forging equipment to be delivered to your court.\n\nWhile you wait, Mograine asks that you clear out some of our enemies to help cover for my absence.\n\nIt was in the letter. Shame it's all shredded up so you can't read it.", completion = "Good. I've arranged everything needed on our side.\n\nI'll be there.", objectives = "Complete World Quests in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62610] = { id = 62610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyphae Patrol: The Stalks", description = "<Marasmius sighs.> \n\nThey're at it again, up in the Stalks.\n\nSeems like we didn't give them enough of a thrashing the first time, eh? What say you and I team up again and teach those younglings a lesson they won't forget?\n\nLet me know when you're ready and we'll get 'em, just like before!", progress = "Let's go, before they do any more damage!", completion = "Hmph, serves them right. Think they can go stomping around my grove? I am the only one who gets to do any stomping! I am the one who stomps!", objectives = "Ride the fae rings and slay 30 Masked Invaders in The Stalks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62611] = { id = 62611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyphae Patrol: Heartwood Grove", description = "Those masked fiends have taken over Heartwood Grove, and I mean to stop their plans.\n\nHeartwood Grove was so beautiful before. And now, it's... No matter. We're going to fix this, you and me. Right now.\n\nCome, join me in battle. We'll give those monsters a thrashing that will make their masters think twice before desecrating that sacred place again!", progress = "Hurry up. I won't stand to let them spend one moment more in that grove.", completion = "There, it's done. They should be driven back, if only for a while. I appreciate the help.", objectives = "Ride the fae rings and slay 30 Possessed Desecrators in Heartwood Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62612] = { id = 62612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venthyr Arsenal", description = "<Forgy reads the letter you hand him.>\n\nAh, Rendle sent you. Should've said so.\n\nNo problem. I'll get you everything you need to be bashing skulls at that court.\n\nGonna need some help convincing my boss for the time off, though.\n\nReal stick in the muck, yeah?\n\nSay you take care of some of the troubles around here, tell everyone it's for me--that'll do it.", completion = "Nice work. Boss gave the all-clear for me time off.\n\nSee you there, Maw Walker.", objectives = "Complete World Quests in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62613] = { id = 62613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kyrian Arsenal", description = "<Forgelite Sophone reads the letter you hand her.>\n\nI see.\n\nWherever I may serve, I will go.\n\nAre you willing to do the same? Will you serve Bastion where it has need?", completion = "My hammer is yours.", objectives = "Complete World Quests in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62614] = { id = 62614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyphae Patrol: Eventide Grove", description = "I hope you're ready to fight.\n\nThe Drust are bolstering their forces in Eventide Grove. Most of Ardenweald doesn't remember them, but I do. You have to completely root them out to be rid of their presence, or they'll grow right back, tougher than ever.\n\nCome with me. We're going to exterminate every last one of them. Let me know when you're ready.", progress = "Quickly, before they spread any further into Ardenweald. Now's our chance.", completion = "Good work. They're still holed up in Darkreach, but that's the best we can do for now. Keep 'em contained, and then we'll burn them out.", objectives = "Ride the fae rings and slay 30 Possessed Invaders in Eventide Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62615] = { id = 62615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyphae Patrol: Gossamer Cliffs", description = "Bad news from the Gossamer Cliffs. We need to help.\n\nThe varmints terrorizing the poor silk striders have become more cruel and aggressive lately. The silk striders are important to Ardenweald; more important than almost anyone else knows. We can't lose any more.\n\nLet me know when you're ready to go and we'll scare those gits away for good!", progress = "Quickly! The striders are counting on us!", completion = "The little misses should be safe for now. Their purpose is vital to Ardenweald, and I won't have any more of them dying on my watch!", objectives = "Ride the fae rings and slay 30 Blackthorn Assailants in the Gossamer Cliffs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62616] = { id = 62616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Night Fae Arsenal", description = "<Gormsmith Cavina reads the letter you hand him.>\n\nI'm not surprised the Hunt-Captain sent you to me. I am the finest gormsmith in all of Ardenweald, afterall.\n\nHer orders are clear and I'm happy to help.\n\nWe'll need you to take on some extra patrols to make up for the lost time and resources.\n\nSound fair?", completion = "Everything's ready. I'm looking forward to the adventure.", objectives = "Complete World Quests in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62618] = { id = 62618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Odalrik" }
quests[62619] = { id = 62619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Meandering Story", description = "<A quick glance at this heavy tome reveals flowery language and a plot that doesn't seem to go anyplace. At least not in the first few chapters.\n\nThere is some dirt on the cover, but the damage isn't too bad. This book doesn't seem to have found itself in too much trouble-- a bit like its plot.\n\nArchivist Dreyden would probably be pleased to have his book back.>", completion = "Oh! You found one of my books! Thank you so much for returning it to me.", objectives = "Bring the Meandering Story to Archivist Dreyden in the Grove of Memory.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62620] = { id = 62620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wandering Tale", description = "<This book might have a point, but the author is taking every possible detour along the way. Or maybe it's about the journey and not the destination...\n\nIn any case, Archivist Dreyden would probably be pleased to have his book back.>", completion = "I was just thinking about this book! I had hoped it would come back on its own. Thank you for returning it to me.", objectives = "Bring the Wandering Tale to Archivist Dreyden in the Grove of Memory.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62621] = { id = 62621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Escapist Novel", description = "<Action, adventure, thrills, chills... This book has it all! Penned by a mortal soul who led an amazing life, this book is a page-turner. \n\nBut is it true? Could one person fight conspiracies, ancient evils, vast enemy armies, demons and even gods in a single lifetime?\n\nOn further reflection, it could be true, but what is a \"duck\" this book speaks of? That part sounds fake.\n\nStill... it was a good story. Archivist Dreyden would probably be pleased to have his book back.>", completion = "This was a good tale! Oh, I do hope the soul who wrote it down is doing okay in this drought! Oh dear me. Thank you for returning it to me.", objectives = "Bring the Escapist Novel to Archivist Dreyden in the Grove of Memory.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62622] = { id = 62622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Travel Journal", description = "<This book appears to be a travelogue of this book's personal journey around Ardenweald! And self-written and published no less!\n\nFlipping towards the end you see yourself enter the picture as a villain, unjustly attacking the book and opening it. \n\nYou read \"This book appears to be a travelogue of this book's personal journey around Ardenweald! And Self-written and-\"\n\nYou hurriedly close the book, feeling queasy. It should go back to Archivist Dreyden.>", completion = "It was writing itself? How fascinating! The feeling of recursion will pass.", objectives = "Bring the Travel Journal to Archivist Dreyden in the Grove of Memory.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62623] = { id = 62623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Naughty Story", description = "<You have held this book for less than five minutes and it has already escaped once, bitten you twice and somehow managed to steal some gold.\n\nThis is not what you were expecting from a \"Naughty Story\" but then again, maybe you should have.\n\nYou bind the book closed so it will hopefully cause a minimum of mischief. Time to bring it to Archivist Dreyden.>", completion = "You found one of my books!\n\nOh. That one.\n\n<Dreyden sighs.>\n\nI suppose I will take it back. Thanks, I guess.", objectives = "Bring the Naughty Story to Archivist Dreyden in the Grove of Memory.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62624] = { id = 62624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Queen's Conservatory", description = "I have heard that you are aiding us in restoring our sanctum, {name}. \n\nThere is a very special magical grove that we know as The Queen's Conservatory. \n\nWithin this magical sanctuary we nurture the spirits of old deities back to life. But its magic has waned with the anima drought. \n\nIt is in need of your help.\n\nIt would mean the world to us if you could start the restoration process by acquiring the resources we need.", progress = "You can go and Speak to Zayhad in your Sanctum to unlock the Queen's Conservatory once you have collected sufficient resources.", completion = "I am so happy to see you have started to help restore the Queen's Conservatory to its former glory.", objectives = "Speak to Zayhad to unlock the Queen's Conservatory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62625] = { id = 62625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare and Unusual Spirit", description = "It's a joy to see the progress you've made in the restoration of the conservatory, {name}!\n\nBut there's still more work to be done.\n\nWe have found another inert spirit. A dark dream is preventing its awakening.\n\nIn this dream, the spirit is caught in the midst of a feud between ancient beings. Both are a bit on the unsavory side, but one is much, much worse than the other!\n\nIf you were to defeat the Father of Sleep, it should nudge the spirit from its slumber. Will you help?", completion = "Another dream vision fulfilled. This is remarkable!", objectives = "Defeat Mueh'zala in De Other Side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62626] = { id = 62626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mullby's Marker", description = "The Marker looks like it might be important to this Mulby fellow. Returning it to him in Maldraxxus might net you a finder's fee.", completion = "You have something for me? Oh my! \n\n<In a quieter voice.> \n\nHow did you get this? Of course I will compensate you for bringing it back to me, that Grandmaster Vole would not have parted with it until he rung me dry. You have no idea what you saved me from.\n\nOh, can you not mention this to Elsie, she would never let me hear the end of it, I swear my betting days are over.", objectives = "Return the marker to the Challenger's Promenade in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62627] = { id = 62627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Spirits Great and Small", description = "This is a most curious place.\n\nSo much energy of rebirth. A fusion of different forms of magic. Not what I expected.\n\nI too was committed to rebirth among my kind. This magic is both known to me, and like nothing I have seen before. Yet it all serves to balance. \n\nIt is not just great spirits of import that help to maintain the cosmic balance.\n\nEven the smallest of creatures can play a role. \n\nI can show you if you like? Visit the remains of one such creature, and we shall rekindle its spirit.", progress = "Return to me when you have found the remains that birthed the spirit animal.", completion = "You have seen them already? Yes, you did. I can tell.", objectives = "Travel to Frostfire in search of the remains", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62628] = { id = 62628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vole's Voucher", description = "<The voucher spells it all out, if you take the voucher to Au'narim at the Challenger's Promenade outside the Theater of Pain in Maldraxxus he should dispense the funds to you from Grandmaster Vole's credit.>", progress = "You wish to make a transaction?", completion = "<Au'narim takes the voucher from you, reads it over.>\n\nVoucher authenticated, approval of funds authorized. Please approach again if you wish to engage in another transaction.", objectives = "Take the voucher to the Challenger's Promenade in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62629] = { id = 62629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Spirits Great and Small", description = "The time has come for us to rekindle another animal spirit.\n\nThis one was lost to fire and raiding in a distant land.\n\nGo. Commune with the creature's remains. Release its spirit so that it may return here.", completion = "You have delivered this spirit back to us. It can now roam free here in the conservatory.", objectives = "Travel to Kun-Lai Summit in search of the remains", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62630] = { id = 62630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Spirits Great and Small", description = "The time has come for us to rekindle another animal spirit.\n\nWhile appearing normal to you, and to the great winged creature that ate it, this creature was in fact somewhat special among its kind. \n\nYou should travel to its grisly resting place and commune with its spirit so that it may join us in the conservatory.", completion = "You have delivered this spirit back to us. It can now roam free here in the conservatory.", objectives = "Travel to Tiragarde Sound in search of the remains", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62631] = { id = 62631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Awaits", description = "When the sign of the emissary shines in the night sky, the stars strengthen existing bonds and forge new ones. Friendship is still not cheaply won, and deeds will prove loyalty, but trust comes more readily during these days. Venture across these lands, and give aid where you may, to prove your worth.", completion = "Well done, {name}.", objectives = "Complete 20 World Quests in the Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62632] = { id = 62632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Burning Path Through Time", description = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62633] = { id = 62633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Frozen Path Through Time", description = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62634] = { id = 62634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shattered Path Through Time", description = "The Destroyer's star shines upon the land with its piercing light as even the spirits retreat to the shadows. This star is unlike any other in the skies, laying bare the weaknesses of even the boldest heroes. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Defeat 5 Timewalking raid bosses or dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62635] = { id = 62635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shrouded Path Through Time", description = "The shrouded star flickers upon the land with its intermittent light ushering in an eerie mist upon the land. This star and the mists bring deep shadows to the land hiding its secrets and dangers. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62636] = { id = 62636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Savage Path Through Time", description = "The brutal star shines upon the land, threatening to trample underfoot all who stand in its path. This star is many things: primal, fierce, and noble. While its influence holds, new paths may open up to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62637] = { id = 62637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Battle", description = "The favorite star of warlords and generals dominates the sky, offering good fortune to tacticians everywhere. Some say that the battle star hones the instincts of commanders to the point of near-prophecy. If ever you were going to test yourself on the field of battle, now is the time.", completion = "I trust your battles went well. And that's not just a turn of phrase. I know they did. I knew they would.", objectives = "Win 4 Battleground matches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62638] = { id = 62638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of War", description = "When the sign of the warrior shines in the night sky, fortune favors the daring. Powerful foes may yield even greater rewards. Venture deep into caverns and strongholds to prove your worth.", completion = "Well done, {name}. I knew you could do it.", objectives = "Complete 4 dungeons on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62639] = { id = 62639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Very Best", description = "This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.", completion = "Well done, {name}. With courage, you have faced every challenge along the way, and battled every day to claim your rightful place.", objectives = "Defeat 5 players through Find Battle with a team of level 25 pets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62640] = { id = 62640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arena Calls", description = "This alignment of the stars is a dire sign, stirring bloodlust and calling warriors to battle to the death in close quarters. Arena masters turn a tidy profit during these days, likely not understanding why their stands are overflowing. Amidst the excitement, great rewards do await those brave, or foolhardy, enough to venture into the arena....", completion = "Well done, {name}. I knew you would do it.", objectives = "Win 10 Arena Skirmish battles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62642] = { id = 62642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - SL - Heroic Random - 1st" }
quests[62643] = { id = 62643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - SL - Heroic Random - Nth" }
quests[62644] = { id = 62644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - SL - Normal Random - 1st" }
quests[62645] = { id = 62645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - SL - Normal Random - Nth" }
quests[62646] = { id = 62646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - SL - Raid Finder - 1st" }
quests[62647] = { id = 62647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - SL - Raid Finder - Nth" }
quests[62653] = { id = 62653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Inquisition", progress = "Archivist Fane can help you acquire an inquisitor's sinstone.", completion = "<Archivist Janeera does not look up from her scroll as she responds to you.>\n\nNoted and logged.", objectives = "Defeat any inquisitor in Halls of Atonement.\n\nArchivist Fane can provide Inquisitor Sinstones to help you in your hunt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62654] = { id = 62654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maw Walker", description = "I believe now it is time for you to leave.\n\nYou are a Maw Walker, one who can activate the waystone between the Maw and the lands beyond. While your friends may not hold the same title, there is a way to send them through the gate. \n\nSouls can be connected. In theory, if you let someone attune themselves to your soul while you activate the waystone, you both should be able to leave. Even fleeting connections may produce some result.\n\nGo with your other two guests and see if my hypothesis is correct.", completion = "You return in one piece. And with not just Darion, but his father as well. You continue to succeed, Maw Walker.", objectives = "Attune with Darion and Alexandros and assist them in leaving the Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62658] = { id = 62658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowlands Dungeon Reward Quest" }
quests[62691] = { id = 62691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Calling in Revendreth", description = "We got a lot of problems out there, boss. Big ones, little ones, really smelly ones, it's a lot.\n\nIf we're gonna take on Denathrius, the first thing we gotta do is clean up right here in Revendreth.\n\nWe get things cleaned up, yeah? Then we get some new allies, and we probably get our hands on some anima to boot.\n\nIt's a call to action, it is. And it's important that we get started right away.\n\nGet on out there and get your boots muddy!", progress = "What do ya want?", completion = "Ya did a good thing today, an' we're safer for it. Never been one to give a compliment, me, but today I gotta say ya did a good one.", objectives = "Complete 3 World Quests in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62692] = { id = 62692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Calling in Bastion", description = "Our forces are weakened by doubt and our temples are under assault. If we are to aid the rest of the Shadowlands, we must begin here, in Bastion.\n\nTravel the golden fields and root out evil wherever you may find it. In time, we will rebuild our forces and our anima stores, and stand tall once more.\n\nToday, you walk the path of courage--it is your calling. Show our people that doubt will not fester here.", progress = "Do the hills echo with the cries of your victories, Maw Walker?", completion = "The hills speak of your faith and honor, and our forces radiate with each victory!\n\nGlory to Bastion, glory to the Archon, glory to the Maw Walker!", objectives = "Complete 3 World Quests in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62693] = { id = 62693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Calling in Ardenweald", description = "Ardenweald is fractured, its roots strangled. Before we can begin to regrow our glades, we must unearth the evils that have festered here.\n\nWe call to you, today, to defend our forests. Take the weald paths through our lands, aiding our allies and defeating our enemies. With these actions, we will renew our forces, and rebuild our anima. In time, hope will blossom.\n\nOur trust is in you, our newest seedling.", progress = "Have you brought hope and faith to our people today?", completion = "Our bonds are stronger, our roots grow deeper, due to your actions this day. We will hold strong against the onset of foes that plague us, as groves weave together in defense, thanks to you.", objectives = "Complete 3 World Quests in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62694] = { id = 62694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Calling in Maldraxxus", description = "Today marks the beginning of our path to victory.\n\nEnemies surround us on all sides. Aid our troops on the battlefield and return with the resources we need to wage our war.\n\nOnce we have secured our home front, we can direct our efforts outwards.\n\nSuch is your calling. Failure is unacceptable.", progress = "How goes the battle?", completion = "Our rival houses will think twice before stepping foot outside of their strongholds again. Blood and glory to you, Maw Walker.", objectives = "Complete 3 World Quests in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62695] = { id = 62695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Service", description = "An opportunity has arisen that will be perfect for you to display your... prowess... to the denizens of Revendreth.\n\nSpeak with Rendle. That dredger is disturbingly effective when it comes to hatching schemes. He says he has a plan for you.", completion = "It's right good of you to step up and take on this here challenge, it is. We've got a lot of work to do, here in Revendreth, so's I hope you're ready to get a bit dirty.", objectives = "Speak with Rendle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62697] = { id = 62697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Service", description = "<Laurel picks out a sad tune on her harp.>\n\nOur groves wilt and wither,\nand enemies wait at our gates!\nThe forest calls out in sorrow, \n\"Please help us before it's too late!\"\n\n<The melody becomes a call to arms.>\n\nO <huntsman/huntress>, now answer our calling!\nArdenweald is in need of your might!\nEnvoy Blodwyn will give you a mission,\nto ride with the Wild Hunt tonight!", completion = "I thank you for your visit, and entrust you with an important task. To regrow Ardenweald, we must begin by aiding its denizens.", objectives = "Speak with Blodwyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62698] = { id = 62698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call to Service", description = "Elysian Hold requires anima to operate fully. We need as much as we can so it may serve our needs.\n\nOur temples are fraught with challenges. By heeding their call you will recover anima for use within the sanctum here.\n\nSpeak with Hermestes first, who will guide you on the path of courage.", completion = "I knew you would answer the call, Maw Walker. There is much to be done.", objectives = "Speak with Hermestes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62700] = { id = 62700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes of the Tower", description = "Your first step towards obtaining the power is to retrieve... something. Yes, I believe it's coming back to me.", sourceObjective = "Collect 1250 Soul Ash in Torghast.", progress = "Have you recovered what is needed?", completion = "Yes, this should be enough to engrave the runes. Upon lesser equipment, that is. \n\nPotent items will require more... more... Soul Ash. Yes, Soul Ash.\n\nAnd you should hold onto it. I will ask for it when the time comes.", sourceObjectiveStatus = "unverified-source-field" }
quests[62704] = { id = 62704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Threads of Fate", description = "It is my duty to observe the strands of fate. The wondrous possibilities that the Purpose lays before us.\n\nFate flows around you, mortal. It shifts. It changes. But I have stilled its movements to offer you... a choice.\n\nYou may journey through the Shadowlands in the same manner as those who came before you have done.\n\nOr you may choose a different path. One that lets you forge a bond with a covenant now, and move freely through the realms of Death to forge your own destiny.\n\nWhat say you, mortal?", progress = "Fate is not fickle. Should you accept its offer, there will be no turning back.", completion = "Your choice is made. The Purpose will guide you forward.", objectives = "Speak with Fatescribe Roh-Tahl and decide how you want to experience Shadowlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62705] = { id = 62705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scour the Temple" }
quests[62707] = { id = 62707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Elysian Fields", description = "You must travel to Bastion, eternal home of the winged kyrian.\n\nDo not be fooled by their golden fields and shining spires--the kyrian have been weakened by the great anima drought, and face the brink of civil war against their own fallen brethren.\n\nThey will benefit greatly from your aid. Seek one known as Kalisthene in the crossroads called Hero's Rest. She will direct you further.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", completion = "Why have you come to our realm, mortal?", objectives = "Speak to Kalisthene at Hero's Rest in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62712] = { id = 62712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War of Attrition" }
quests[62714] = { id = 62714, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for an Acolyte", description = "The materials you supplied were more than sufficient for my purposes. For that, you have my gratitude.\n\nI think I know how to make the best use of the excess.\n\nA dear friend of mine recently achieved the role of Acolyte in service to the Temple of Purity. You are new here, so I will spare you the details, but it is an honor to serve a temple before one reaches ascension.\n\nI want to celebrate her success with a gift. Will you take this parcel to Acolyte Amalthina?", progress = "Welcome to the Temple of Purity. How may I be of service?", completion = "What is this?\n\n<She opens the parcel. A soft smile spreads over her face.>\n\nThis is wonderful. Thank you.", objectives = "Deliver Klystere's Gift to Acolyte Amalthina in the Temple of Purity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62715] = { id = 62715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than A Gift", description = "You have no idea what you just delivered, do you?\n\n<She opens the parcel to reveal a wreath of Larion plumage.>\n\nI will explain, but first... I wish to return the favor.\n\nKlystere and I frequent a resting place to the north of here, along the path to the Temple of Courage. We planted a flower for our enjoyment, as we spend so much of our free time there.\n\nBring me this bloom, if you would be so kind. Then I will tell you about the significance of this gift.", progress = "Did you find the place I mentioned? And the flower?", completion = "This is perfect. I appreciate your efforts on my behalf.", objectives = "Acquire 1 Cultivated Windblossom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62716] = { id = 62716, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Re-Introductions", description = "Though you have chosen your path, the fate of the Shadowlands has yet to be determined.\n\nThe power of the Banished One grows. It falls to you, and others of your kind, to thwart him.\n\nThe Arbiter's Honored Voice, Tal-Inara, will aid you in choosing a covenant. Bolstering their strength offers our best chance at victory.\n\nLet the Purpose guide you, {name}. Always.", completion = "Ah, {name}. I was wondering when you were going to appear. Your aid is needed.", objectives = "Speak with Tal-Inara within the Enclave in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62717] = { id = 62717, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venari Rep Token Tracking" }
quests[62718] = { id = 62718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Rest", description = "In light of the new arrivals to Bastion, Kalisthene has enabled the anima gateways to Hero's Rest once more!\n\nThose wishing to partake of breathtaking views, unparalleled steward service, and all manner of training and repair facilities should venture to this most remarkable of locations at their earliest convenience.\n\nSimply follow the path north and bear to the right at the crossroads.\n\nKalisthene will personally greet all new arrivals for this most joyous of occasions!", completion = "Welcome to Hero's Rest, crossroads of Bastion. You will find much to aid you in your journey here.", objectives = "Speak to Kalisthene in Hero's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62719] = { id = 62719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Pieces", description = "The final components you'll need to acquire are... vessels... rune vessels! Armor to hold the might that will be imbued.\n\nAnd... powers? No... missives? Yes! Missives will allow your item to enhance your own personal strengths. But they cannot be the same. No, the two must offer different benefits.\n\nAll of these can be obtained from souls with the correct crafting knowledge.\n\nAnd lastly, more of my memories. Memories of the runes, of the powers... of myself.", progress = "Have you acquired the remaining items?", completion = "You've collected all the necessary pieces. Now all that's left is to combine them.\n\nSpeak with me again when you are ready, and I will create the prize you seek.", objectives = "Acquire a Runecarver Memory, an Armor Rune Vessel suitable to your class, and two different Missives. These items can be obtained through crafting, or can be found on the Auction House.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62720] = { id = 62720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Tree" }
quests[62721] = { id = 62721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deconstructing The Problem" }
quests[62723] = { id = 62723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolstering Bastion", description = "You are no aspirant, but I welcome any aid that Oribos might bring us in these dire times.\n\nPlease, aid our people in any way you can. With anima in low supply and the insidious Forsworn encroaching from all sides, there is no shortage of trials to overcome.\n\nDo this for us, and I will see to it myself that our almighty Archon hears of your deeds in service of the kyrian. Mark well my words, and follow the path.", completion = "Word has spread across Bastion of your deeds since your arrival here.\n\nYou have proven yourself a worthy ally of the kyrian. Take this gift in thanks, and go in service.\n\nMay we cross paths again soon.", objectives = "Aid Bastion by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Bastion dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62724] = { id = 62724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ye Olde Test of Strength", description = "A test of strength this be.", sourceObjective = "Complete the Test.", sourceObjectiveStatus = "unverified-source-field" }
quests[62725] = { id = 62725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Test of Guile", description = "A test of wits and guile.", sourceObjective = "Meet the criteria of the test.", sourceObjectiveStatus = "unverified-source-field" }
quests[62726] = { id = 62726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ye Olde Test of Fortitude" }
quests[62727] = { id = 62727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "9.0 Rated PvP Incentive - Shadowlands Season 1 Exclusive Mount" }
quests[62728] = { id = 62728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "9.0 Rated PvP Incentive - Shadowlands Season 1 Saddle", objectives = "You will be able to choose one of these rewards:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62729] = { id = 62729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Oribos", description = "You have proven yourself a worthy ally of Bastion in your time here, {name}. Though I wish you could remain here, there are other realms in the Shadowlands that require aid more.\n\nReturn to Oribos when you are able and seek out Tal-Inara. She will help you decide where to best next focus your efforts.\n\nArchon watch over you.", completion = "You have fulfilled your purpose. Well done.", objectives = "Speak to Tal-Inara in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62730] = { id = 62730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fruit of the Gods", description = "You like sweet fruit? \n\nStewards grow juiciest Purian. It special fruit! You find it many places in Bastion. It used for many things. \n\nEat for nourishment.\n\nGive to bells for blessings.\n\nGive to stewards for treasure.\n\nYou find, I show you how!", progress = "You find sweet Purian?", completion = "Yes, this very sweet and ripe. Must use quickly, before it spoils!", objectives = "Bring Elios 1 Ripe Purian fruit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62732] = { id = 62732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locus Focus" }
quests[62733] = { id = 62733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sweetest Tribute", description = "Purian good to eat, yes, but better to give.\n\nYou find locked Silver Strongbox near steward statue. Give Ripe Purian fruit as tribute.\n\nThen get nice surprise!\n\nYou try?", progress = "You give Purian yet?", completion = "I hope you liked your surprise! \n\nYou find more silver strongboxes, give Ripe Purian tribute!\n\nOh-ho! You want key to my Golden Chest? Ask me about Steward of the Day!", objectives = "Place a Ripe Purian fruit in the steward statue Tribute Tray.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62735] = { id = 62735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostile Recollection" }
quests[62736] = { id = 62736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maldraxxi Eviction Notice" }
quests[62737] = { id = 62737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aspirant For a Day" }
quests[62738] = { id = 62738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fresh Blade", description = "Though they were once unified in defending the Shadowlands, the houses of Maldraxxus have turned against each other.\n\nTheir armies clash within their realm and have even orchestrated an assault on Bastion. Now only the Necrolords remain loyal to the Primus.\n\nSpeak to Secutor Mevix at the Bleak Redoubt in Maldraxxus. His tactical skills will ensure you are sent where you are most needed.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide you with transportation.", completion = "Ah, another blade on our side! And you aren't even dead yet!", objectives = "Speak to Secutor Mevix at the Bleak Redoubt in Maldraxxus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62739] = { id = 62739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Balance", description = "Ardenweald is crucial to the cycle of rebirth for nature spirits that enter their realm.\n\nUnfortunately, the anima drought has led to the loss of entire groves--souls that will never complete their cycle.\n\nNow foes seek to destroy what remains of the once tranquil forests, threatening the already beleaguered Court of Night. \n\nLady Moonberry of the Court has requested aid. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", completion = "Welcome! What brings you to the Heart of the Forest?", objectives = "Speak to Lady Moonberry at the Heart of the Forest in Ardenweald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62740] = { id = 62740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Aspirations", description = "Prince Renathal has started a daring rebellion against his father, the nefarious Sire Denathrius who betrayed us all by pouring Revendreth's vast anima stores into the Maw.\n\nYou must travel to Revendreth and aid Renathal in his efforts. He is our best hope at restoring Revendreth to order.\n\nPathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", completion = "And to what do I owe the pleasure of a mortal visiting Revendreth at such an...inopportune time?", objectives = "Speak to Prince Renathal in the crypt beneath Darkhaven in Revendreth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62741] = { id = 62741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Choice of Action" }
quests[62742] = { id = 62742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avoid 'Em Like the Plague" }
quests[62743] = { id = 62743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decaying Situation" }
quests[62748] = { id = 62748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying Maldraxxus", description = "We need all the help we can get! It's taking all we have to hold our ground against the other houses, let alone gain any ground against them.\n\nTruth be told, your blade will be welcome anywhere. There are no shortage of battles to be won, foes to be toppled, or weary soldiers to be relieved.\n\nHelp us regain control of Maldraxxus, and in the name of the Primus I will see you are amply rewarded.", completion = "All who have reported back to me have said the same--you have brought victory upon victory to the House of the Chosen!\n\nOn behalf of all who serve the Primus, you have my eternal gratitude.", objectives = "Aid Maldraxxus by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Maldraxxus dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62761] = { id = 62761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Oribos", description = "I wouldn't be a tactician if I didn't recognize when the mission is complete.\n\nMuch remains to be done before Maldraxxus can stand tall once again, but that day will come thanks to your efforts. \n\nThere are other realms in need of your skills more than us. You should return to Oribos and see to it that they receive it.", completion = "You have done well in Maldraxxus. Their path forward is clear.", objectives = "Speak to Tal-Inara in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62763] = { id = 62763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Support the Court", description = "Groves are under attack everywhere! There simply aren't enough of us to protect them all!\n\nYou just might be our only hope.\n\nWe must restore order, or more precious souls will be lost to us. Please, help anyone you can, anywhere you can. My heart cannot bear to see any more pain!\n\nI'll make sure the Winter Queen hears of your deeds, don't you worry!", completion = "You have done a great service to not only Ardenweald, but the countless nature spirits we protect.\n\nThank you. Today you are a hero of Ardenweald!", objectives = "Defend Ardenweald by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Ardenweald dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62773] = { id = 62773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreamshrine Basin" }
quests[62774] = { id = 62774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tranquil Pools" }
quests[62775] = { id = 62775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waning Grove" }
quests[62776] = { id = 62776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Oribos", description = "I wish you could stay and relax here, maybe enjoy a play at the Star Lake Amphitheater, but there's simply no time!\n\nThere are other realms out there that need your help, too.\n\nYou will always be a friend of the Court, but I'm afraid you must return to Oribos. The Shadowlands needs you!", completion = "Your efforts in Ardenweald have not gone unnoticed, Maw Walker.", objectives = "Speak to Tal-Inara in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62778] = { id = 62778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinforcing Revendreth", description = "Denathrius must be stopped at all costs. However, we've no hope of taking him out while his forces still control much of Revendreth.\n\nIf you are here to aid us, then there is no shortage of work to be done. Disposing of my father's many allies being chief among that work, of course, but any aid you can provide will be of use.\n\nThere is too much at stake for all the Shadowlands if we fail. I will see to it that you are handsomely rewarded for your efforts.", completion = "You have my sincere gratitude for aiding our cause. Together we will see Denathrius's hold on our realm broken, and with it win the freedom of my people.\n\nI cannot offer as much as I would like, but I hope it will suffice until our victory is achieved.", objectives = "Aid Revendreth by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Revendreth dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62779] = { id = 62779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Oribos", description = "I truly wish you could remain here and aid our cause--it is truly the most pressing manner in all the Shadowlands--but Revendreth alone cannot stand against the growing darkness.\n\nYou must return to Oribos and ensure the other realms do not falter in their commitments. Tal-Inara will be able to guide you appropriately.\n\nThank you once again for your aid, mortal. May our paths cross again.", completion = "Revendreth stands stronger for your efforts. The Purpose is clear.", objectives = "Speak to Tal-Inara in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62780] = { id = 62780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parasites of Reality" }
quests[62781] = { id = 62781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ash You Like It" }
quests[62782] = { id = 62782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Banewood" }
quests[62783] = { id = 62783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalking Fear" }
quests[62784] = { id = 62784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charlatans of Ceremony" }
quests[62785] = { id = 62785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Could Be A Contender", description = "Hold up there, <brother/sister>. \n\nIf you are serious about fighting in the Arena you're going to need a manager. \nLucky for you, <brother/sister>, I know a guy. He's just had some openings in his roster of fighters and you look like just the type of {class} he needs to fill his ranks.\n\nName is Louison, you can find him at the gate just east of here.\n\nTell him I sent ya, <brother/sister>.", completion = "Oh, Anzio sent you? Hah, and here I was thinking you were just another nosy fan.\n\nYeah, you look like just the {class} I need!", objectives = "Speak with Louison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62789] = { id = 62789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Great Renown", description = "As you aid our sacred covenant across the Shadowlands, your connection to it shall grow ever stronger.\n\nYour Renown will afford you many benefits over time.\n\nSeek out Iona Skyblade at the front of the hold, near the Crest of Ascension. She will show you the glory of the path.", completion = "Greetings, Maw Walker. It is an honor.", objectives = "Speak with Iona Skyblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62790] = { id = 62790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path Provides", description = "All who follow the path are granted precious gifts by virtue of their connection with our covenant.\n\nThe strength of that bond, known as Renown, is reflected in the shining spires of Elysian Hold itself. Though you have yet to gain Renown, you will as you aid us across the Shadowlands.\n\nWhen you are ready, I will show you all that the path can provide.", progress = "Some say it is the Archon herself who grants our covenant its strength.", completion = "Follow the path always, and all will be well.", objectives = "Examine your Renown with the Kyrian Covenant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62791] = { id = 62791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Most Precious Resource", description = "You have fulfilled your calling, Maw Walker, and brought peace to our realm.\n\nStay vigilant, for others will similarly call upon you in time.\n\nThe anima you have so dutifully recovered will be of great use in the hold. Bring it to Haephus at once. He will ensure it is kept safe until it is needed.\n\nGo in service.", completion = "The Maw Walker returns triumphant! Have you any anima on hand?", objectives = "Speak to Haephus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62792] = { id = 62792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Reservoir", description = "As the flow of anima withered within Bastion, our mighty Archon entrusted me with guarding our stores until they are needed.\n\nYou may deposit any anima you recover into the reservoir here. By my life, and by the glory of the Archon, I will ensure they are kept safe.", progress = "Anima is best kept here, safe from our enemies who would take it from us.", completion = "Every drop is precious. I will keep it safe here.", objectives = "Deposit Anima into your sanctum's Reservoir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62793] = { id = 62793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's All Coming Together", description = "Our brothers and sisters are spread thin fighting the Forsworn, maintaining order among aspirants waiting to ascend, and countless other duties.\n\nThe willing souls you recovered from the Maw will be a great boon to our capabilities in these dire times.\n\nGo to Haephus at once--he has long been searching for aid in activating some of our sanctum's most powerful features. It is time we saw Elysian Hold brought to its full potential.", completion = "I could feel their presence as soon as you brought them to the hold. What a momentous occasion!", objectives = "Speak to Haephus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62794] = { id = 62794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enhancing the Hold", description = "As thanks for your efforts in recovering the anima and souls we now have available, you may decide which of Elysian Hold's features we upgrade first.\n\nOnce active, it shall expand our capabilities to help not only Bastion, but all the Shadowlands.\n\nDo not worry--as you continue to recover anima and willing souls we will activate them all in time. For now, a single upgrade must suffice.", progress = "Take your time. The first step on the path is always the most difficult.", completion = "A wise decision. It will take some time to activate, but all good things are worth waiting for, are they not?", objectives = "Start a Sanctum Upgrade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62795] = { id = 62795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Conduit for Good", description = "While the gifts your bond shall bring you are substantial, you may also empower yourself further through the use of conduits.\n\nConduits act to channel the energy of your soulbind into your form more directly, increasing your potential in a myriad of ways.\n\nUse the ones I have given you as a test of this power, but fear not--you will find others as you aid the Shadowlands.", progress = "This is a crucial step in the path.", completion = "Your soulbind will grow alongside you in time, but your training is complete for now.", objectives = "Add the Conduits to the Forge of Bonds, then apply one to a slot on Pelagos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62796] = { id = 62796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Adrestes", description = "Baine suffers within Torghast, but at least we know that he yet lives.\n\nRushing to his rescue would prove disastrous without a plan of attack. I will see to preparing one.\n\nIn the meantime, I suggest you bring the souls you rescued to Elysian Hold.\n\nThe kyrian are vital to the Shadowlands. If Bastion remains in turmoil, then all might soon be lost.", completion = "Welcome back, Maw Walker. Our work has not paused in your absence.", objectives = "Report to Polemarch Adrestes at Elysian Hold in Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62797] = { id = 62797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vessels of Metal", description = "You have the bearing of one familiar with the art of smithing. But perhaps you have more to learn.\n\nVessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you.\n\nHmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way.\n\nWhat's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", completion = "<Au'berk inspects what you brought to him.>\n\nA memory? Fascinating... With this knowledge, I can teach you to craft armors capable of holding immense power. \n\nFor a price, of course.", objectives = "Bring the memory back to Smith Au'berk in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62798] = { id = 62798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vessels of Leather and Bone", description = "You have the bearing of one familiar with the art of leatherworking. But perhaps you have more to learn.\n\nVessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you.\n\nHmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way.\n\nWhat's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", completion = "<Au'qil inspects what you brought to him.>\n\nA memory? Fascinating... With this knowledge, I can teach you to craft armors capable of holding immense power. \n\nFor a price, of course.", objectives = "Bring the memory back to Tanner Au'qil in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62799] = { id = 62799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vessels of the Thread", description = "You have the bearing of one familiar with the art of thread work. But perhaps you have more to learn.\n\nVessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you.\n\nHmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way.\n\nWhat's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", completion = "<Au'phes inspects what you brought to him.>\n\nA memory? Fascinating... With this knowledge, I can teach you to craft armors capable of holding immense power. \n\nFor a price, of course.", objectives = "Bring the memory back to Stitcher Au'phes in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62800] = { id = 62800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vessels of Jewels", description = "You have the bearing of a lapidary. Though familiar with the art of jewelcraft, perhaps there is yet more to learn.\n\nVessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you.\n\nHmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way.\n\nWhat's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", completion = "<Au'vesk inspects what you brought to him.>\n\nA memory? Fascinating... With this knowledge, I can teach you to craft jewelry capable of holding immense power. \n\nFor a price, of course.", objectives = "Bring the memory back to Appraiser Au'vesk in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62801] = { id = 62801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Fate", description = "I am the Arbiter's fatescribe. It is my duty to observe the strands of destiny that the Purpose lays before us.\n\nFate flows through you, mortal, as you journey through the Shadowlands. And now it offers you... a choice.\n\nReturn to Oribos, {name}, that I might help guide your path.\n\nThe Purpose is our way.", completion = "Welcome, mortal.\n\nAllow me to explain the choice that the Purpose has set before you.", objectives = "Meet Fatescribe Roh-Tahl in Oribos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[62804] = { id = 62804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling the Tanks", description = "<The containment pack appears to be intact, albeit empty. Perhaps refilling it with the appropriate mixture of liquids will render it functional once more.\n\nSlaying the correct combination of slimes should provide all the fluid necessary.>", completion = "An amazing find! You seem to have salvaged a fully charged unit... just throw this switch to activate it!", objectives = "Slay the variety of slimes to fill the tanks with fluid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
